// ---------- Server (when the FastAPI app serves this page) ----------
let LIVE = false;   // true when /api/state answers: the server owns the shared state
let busy = false;   // a payment is in flight
const SHARED = ['step', 'loan', 'day', 'feed', 'eventIds', 'lastSale', 'seq', 'auth', 'rails', 'mode',
  'cliente', 'clienteReal', 'clienteWallet', 'clienteLimit', 'tenderaWallet', 'disburse', 'lenderWallet'];

function applyServer(s) {
  for (const k of SHARED) st[k] = s[k] === undefined ? null : s[k];
  if (s.step !== 'borrador') st.offer = s.offer;                     // the draft offer lives on the lender's phone
  if (s.step === 'activo' || s.step === 'pagado') st.caps = s.caps;  // the draft caps live on the tendera's phone
}

async function api(path, body, method = 'POST') {
  const opts = method === 'GET' ? {} : { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}) };
  const r = await fetch('/api' + path, opts);
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(typeof data.detail === 'string' ? data.detail : `Error ${r.status}`);
  if (data.state) applyServer(data.state);
  return data;
}

async function connect() {
  if (!location.protocol.startsWith('http')) return;  // opened from disk: everything stays local
  try {
    const r = await fetch('/api/state', { cache: 'no-store' });
    if (!r.ok) return;
    applyServer(await r.json());
    LIVE = true;
  } catch (err) { return; }
  render();
  const es = new EventSource('/api/events');
  es.onmessage = (ev) => {
    const s = JSON.parse(ev.data);
    const wasStep = st.step, top = st.feed.length ? st.feed[0].id : 0;
    const wasLinked = !!(st.cliente && st.cliente.linked);
    applyServer(s);
    originRole = null;
    render();
    if (!wasLinked && s.cliente && s.cliente.linked) {
      ping('cliente');
      toast('cliente', '✅ Billetera vinculada. Ya puedes pagar');
      announce('Carlos vinculó su billetera. Ya puede pagar en la tienda.');
    }
    if (wasStep === 'enviada' && s.step === 'desembolso') {
      ping('prestamista');
      toast('prestamista', `✅ ${TENDERA} autorizó. Ahora envía el dinero`);
      announce(`${TENDERA} autorizó el permiso. Falta que ${LENDER} envíe el dinero.`);
    }
    if (wasStep === 'desembolso' && s.step === 'activo') celebrateActivation(s.loan.principal, false);  // real money moved
    else if (!busy && s.feed.length && s.feed[0].id > top) { ping('tendera'); ping('prestamista'); }  // changed from another window
  };
}

function celebrateActivation(principal, real) {
  if (!real) flyCoin(phoneEl('prestamista'), 'tendera', money(principal), 300);
  ping('prestamista', 100);
  ping('tendera', 1300);
  toast('prestamista', real ? `✅ ${TENDERA} autorizó en su billetera` : `✅ ${TENDERA} autorizó. Le enviaste ${money(principal)}`, 100);
