  <span class="role">Deudor</span>
  <span class="wallet" id="walletLabel"></span>
  <span class="spacer"></span>
</header>

<main>
  <section class="card" aria-labelledby="offerTitle">
    <h1 id="offerTitle">Oferta de préstamo</h1>
    <div class="notice error" id="fileWarning" hidden>Abre esta página desde el servidor (por ejemplo <code>http://localhost:8000/demo/deudor.html</code>). Abierta como archivo no puede llamar a la API.</div>

    <div class="waiting" id="waiting">
      <div class="big">Esperando condiciones</div>
      <p>Cuando el prestador envíe un préstamo, aparecerá aquí.</p>
    </div>

    <div id="offer" hidden>
      <p class="sub">Revisa las condiciones antes de responder.</p>
      <dl class="terms">
        <div class="kv"><dt>Monto que recibes</dt><dd id="tPrincipal"></dd></div>
        <div class="kv"><dt>Tasa de interés</dt><dd id="tRate"></dd></div>
        <div class="kv"><dt>Total a pagar</dt><dd id="tTotal"></dd></div>
        <div class="kv"><dt>Porcentaje de cada venta</dt><dd id="tSale"></dd></div>
        <div class="kv"><dt>Plazo</dt><dd id="tTerm"></dd></div>
      </dl>
      <div class="notice info" id="offerHint">Si apruebas, tu billetera te pedirá autorizar dos permisos: cobrar como máximo el total a pagar y leer tus ventas.</div>
      <div class="notice error" id="offerError" hidden></div>
      <div class="row" id="offerActions">
        <button class="btn ghost" id="rejectBtn" type="button">Rechazar</button>
        <button class="btn" id="approveBtn" type="button">Aprobar</button>
      </div>
      <div class="notice" id="offerResult" hidden></div>
    </div>
  </section>

  <section class="card" aria-labelledby="statusTitle">
    <h1 id="statusTitle">Estado de tu préstamo</h1>
    <p class="sub" id="loanIdLabel">Sin préstamo todavía.</p>
    <dl>
      <div class="kv"><dt>Permiso de cobro</dt><dd id="sGrant">—</dd></div>
      <div class="kv"><dt>Desembolso recibido</dt><dd id="sDisbursed">—</dd></div>
      <div class="kv"><dt>Saldo pendiente</dt><dd id="sBalance">—</dd></div>
    </dl>
    <div class="week" id="weekBox" hidden>
      <div class="label">Cobrado esta semana</div>
      <div class="big num" id="sWeek">—</div>
      <div class="sub" id="sWeekDetail"></div>
    </div>
    <div id="collectionsBox" hidden>
      <h2>Cobros realizados</h2>
      <ul class="collections" id="collections"></ul>
      <div class="poll" id="pollLabel" aria-live="polite"></div>
    </div>
  </section>

  <section class="card full" aria-labelledby="logTitle">
    <div class="log-head">
      <h2 id="logTitle">Registro de llamadas a la API</h2>
      <span class="spacer"></span>
      <button class="btn ghost small" id="clearLog" type="button">Limpiar registro</button>
    </div>
    <div class="log-wrap">
      <table class="log">
        <tbody id="logBody"><tr><td class="empty">Sin llamadas todavía.</td></tr></tbody>
      </table>
    </div>
  </section>
</main>

<script>
// ---------- Configuración ----------
const API_BASE = '';  // misma URL que esta página (FastAPI sirve /demo). Cámbiala si la API vive en otro sitio.
const BORROWER_WALLET = 'https://ilp.interledger-test.dev/deudor';
const SHARED_KEY = 'abbo:prestamo';   // estado compartido entre las dos pestañas (localStorage)
const LOG_KEY = 'abbo:log:deudor';
const POLL_MS = 10000;
const ASSET_SCALE = 2;                 // COP en las billeteras de prueba
const MINUTES_PER_DAY = 1440;

const $ = (s) => document.querySelector(s);
const money = (minor) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 2 })
  .format(Number(minor) / 10 ** ASSET_SCALE);
const when = (iso) => new Date(iso).toLocaleString('es-CO', { dateStyle: 'medium', timeStyle: 'short' });

// ---------- Estado compartido ----------
function readShared() { try { return JSON.parse(localStorage.getItem(SHARED_KEY)) || null; } catch (e) { return null; } }
function writeShared(patch) {
  const prev = readShared() || {};
  const next = { ...prev, ...patch, updatedAt: new Date().toISOString() };
  if (patch.status && patch.status !== prev.status) next.history = [...(prev.history || []), { status: patch.status, at: next.updatedAt }];
  try { localStorage.setItem(SHARED_KEY, JSON.stringify(next)); } catch (e) {}
  render();
  return next;
}

// ---------- Registro de llamadas ----------
function readLog() { try { return JSON.parse(localStorage.getItem(LOG_KEY)) || []; } catch (e) { return []; } }
function addLog(entry) {
  const log = [entry, ...readLog()].slice(0, 80);
  try { localStorage.setItem(LOG_KEY, JSON.stringify(log)); } catch (e) {}
  renderLog();
}
function summarize(data) {
  if (data == null) return '(sin cuerpo)';
  const text = typeof data === 'string' ? data : JSON.stringify(data);
  return text.length > 260 ? text.slice(0, 260) + '…' : text;
}
async function api(method, path, body) {
  const started = new Date();
  let res, data;
  try {
    res = await fetch(API_BASE + path, {
      method,
      headers: { 'Content-Type': 'application/json', 'ngrok-skip-browser-warning': '1' },
      body: body ? JSON.stringify(body) : undefined,
    });
    data = await res.json().catch(() => null);
  } catch (err) {
    addLog({ at: started.toISOString(), ep: `${method} ${path}`, code: 'RED', ok: false, sum: String(err) });
    throw new Error('No se pudo conectar con la API.');
  }
  addLog({ at: started.toISOString(), ep: `${method} ${path}`, code: res.status, ok: res.ok, sum: summarize(data) });
  if (!res.ok) throw new Error(typeof data?.detail === 'string' ? data.detail : `Error ${res.status}`);
  return data;
}

// ---------- Flujo ----------
let offerError = '';

async function approve() {
  const s = readShared();
  if (!s || s.status !== 'enviado') return;
  offerError = '';
  writeShared({ status: 'aceptado' });
  const t = s.terms;
  const termMinutes = t.termDays * MINUTES_PER_DAY;
  const here = location.origin + location.pathname;
  try {
    const r = await api('POST', '/loans', {
      loan_id: s.loanId,
      borrower_wallet: s.borrowerWallet,
      lender_wallet: s.lenderWallet,
      amount_value: String(t.totalMinor),        // deuda = capital + interés
      principal_value: String(t.principalMinor), // lo que desembolsa el prestador
      weekly_cap_value: String(t.totalMinor),    // permiso de cobro: como máximo el total...
      term_minutes: termMinutes,
      period_minutes: termMinutes,               // ...en un solo periodo que dura todo el plazo
      repayment_rate_percent: t.salePct,
      borrower_return_url: here,
      lender_return_url: new URL('prestador.html', here).href,
    });
    writeShared({ status: 'esperando_permiso' });
    location.href = r.approve_url;  // la billetera vuelve a esta página con el resultado
  } catch (err) {
    offerError = `No se pudo crear el préstamo: ${err.message}`;
    writeShared({ status: 'enviado' });
  }
}

function reject() {
  const s = readShared();
  if (!s || s.status !== 'enviado') return;
  writeShared({ status: 'rechazado' });
}

// Vuelta desde la billetera del deudor (callback del backend → esta página)
async function handleReturn() {
  const params = new URLSearchParams(location.search);
  const event = params.get('event');
  const loanId = params.get('loan_id');
  if (!event) return;
  history.replaceState(null, '', location.pathname);
  if (event === 'grant_approved') {
    let loan = null;
    try { loan = await api('GET', `/loans/${encodeURIComponent(loanId)}`); } catch (err) { /* ya quedó en el registro */ }
    writeShared({ status: 'permiso_aprobado', loan });  // el prestador reacciona y desembolsa
  } else if (event === 'grant_rejected') {
    writeShared({ status: 'permiso_rechazado' });
  }
}

// Solo lectura: el prestador es quien cobra (sync-sales); aquí solo se consulta el préstamo
let pollTimer = null;
let ownLoan = null;
async function pollLoan() {
  const s = readShared();
  if (!s || !['desembolsado', 'pagado'].includes(s.status)) { pollTimer = null; return; }
  try {
    ownLoan = await api('GET', `/loans/${encodeURIComponent(s.loanId)}`);
    $('#pollLabel').textContent = `Actualizado a las ${new Date().toLocaleTimeString('es-CO')}.`;
  } catch (err) {
    $('#pollLabel').textContent = `No se pudo actualizar: ${err.message}`;
  }
  render();
  pollTimer = s.status === 'desembolsado' ? setTimeout(pollLoan, POLL_MS) : null;
}
function ensurePolling() {
  const st = readShared()?.status;
  if (!pollTimer && (st === 'desembolsado' || st === 'pagado')) pollLoan();
}

// ---------- Pintar ----------
function weekStart() {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7));  // lunes
  return d;
}
function newestLoan(s) {
  // El préstamo más reciente entre lo que trae el prestador y lo que consulta esta pestaña
  const a = s.loan, b = ownLoan;
  if (!a) return b; if (!b) return a;
  return (b.repayments || []).length >= (a.repayments || []).length ? b : a;
}
function render() {
  const s = readShared();
  const hasOffer = !!(s && s.terms);
  $('#waiting').hidden = hasOffer;
  $('#offer').hidden = !hasOffer;
  if (!hasOffer) {
    $('#loanIdLabel').textContent = 'Sin préstamo todavía.';
    for (const id of ['sGrant', 'sDisbursed', 'sBalance']) $('#' + id).textContent = '—';
    $('#weekBox').hidden = true; $('#collectionsBox').hidden = true;
    return;
  }
  const t = s.terms;
  $('#tPrincipal').textContent = money(t.principalMinor);
  $('#tRate').textContent = t.ratePct + ' %';
  $('#tTotal').textContent = money(t.totalMinor);
  $('#tSale').textContent = t.salePct + ' %';
  $('#tTerm').textContent = t.termDays + (t.termDays === 1 ? ' día' : ' días');

  const pending = s.status === 'enviado';
  $('#offerActions').hidden = !pending;
  $('#offerHint').hidden = !pending;
  $('#offerError').hidden = !offerError;
  $('#offerError').textContent = offerError;
  const result = $('#offerResult');
  const RESULTS = {
    rechazado: ['error', 'Rechazaste la oferta. Se le avisó al prestador.'],
    aceptado: ['info', 'Creando el préstamo…'],
    esperando_permiso: ['info', 'Redirigiendo a tu billetera para autorizar los permisos…'],
    permiso_rechazado: ['error', 'No autorizaste los permisos en tu billetera. El préstamo no se desembolsa.'],
    permiso_aprobado: ['ok', 'Aprobaste la oferta y los permisos. Esperando que el prestador envíe el dinero.'],
    desembolsando: ['ok', 'El prestador está autorizando el envío del dinero.'],
    desembolso_rechazado: ['info', 'El prestador todavía no envía el dinero.'],
    desembolsado: ['ok', 'Recibiste el dinero. Cada venta paga una parte del préstamo.'],
    pagado: ['ok', 'Pagaste el préstamo por completo.'],
  };
  const r = RESULTS[s.status];
  result.hidden = !r;
  if (r) { result.className = 'notice ' + r[0]; result.textContent = r[1]; }

  $('#loanIdLabel').textContent = `Préstamo ${s.loanId}`;
  const GRANT = {
    enviado: 'Pendiente', rechazado: 'No aplica', aceptado: 'Pendiente', esperando_permiso: 'En tu billetera…',
    permiso_rechazado: 'Rechazado', permiso_aprobado: 'Aprobado', desembolsando: 'Aprobado',
    desembolso_rechazado: 'Aprobado', desembolsado: 'Aprobado', pagado: 'Finalizado',
  };
  const loan = newestLoan(s);
  const cap = loan?.weekly_cap ? ` · hasta ${money(loan.weekly_cap)}` : '';
  $('#sGrant').textContent = (GRANT[s.status] || '—') + (['permiso_aprobado', 'desembolsando', 'desembolso_rechazado', 'desembolsado'].includes(s.status) ? cap : '');

  const disbursed = ['desembolsado', 'pagado'].includes(s.status);
  $('#sDisbursed').textContent = disbursed
    ? `${money(loan?.principal ?? t.principalMinor)}${loan?.disbursed_at ? ' · ' + when(loan.disbursed_at) : ''}`
    : 'Todavía no';
  $('#sBalance').textContent = disbursed ? money(loan?.balance ?? t.totalMinor) : money(t.totalMinor);

  $('#weekBox').hidden = !disbursed;
  $('#collectionsBox').hidden = !disbursed;
  if (!disbursed) return;
  const reps = loan?.repayments || [];
  const since = weekStart();
  const thisWeek = reps.filter((x) => new Date(x.paid_at) >= since);
  $('#sWeek').textContent = money(thisWeek.reduce((sum, x) => sum + Number(x.deduction), 0));
  $('#sWeekDetail').textContent = `${thisWeek.length} ${thisWeek.length === 1 ? 'cobro' : 'cobros'} desde el lunes ${since.toLocaleDateString('es-CO', { day: 'numeric', month: 'long' })}.`;
  const list = $('#collections');
  list.innerHTML = '';
  if (!reps.length) list.innerHTML = '<li class="empty">Aún no hay cobros. Se hacen solos cuando recibes una venta.</li>';
  for (const x of [...reps].reverse()) {
    const li = document.createElement('li');
    li.innerHTML = '<span></span><span class="amt out"></span>';
    li.children[0].textContent = when(x.paid_at);
    li.children[1].textContent = '− ' + money(x.deduction);
    list.appendChild(li);
  }
}
function renderLog() {
  const body = $('#logBody');
  const log = readLog();
  body.innerHTML = '';
  if (!log.length) { body.innerHTML = '<tr><td class="empty">Sin llamadas todavía.</td></tr>'; return; }
  for (const e of log) {
    const tr = document.createElement('tr');
    tr.innerHTML = '<td class="time"></td><td class="ep"></td><td class="code"></td><td class="sum"></td>';
    tr.children[0].textContent = new Date(e.at).toLocaleTimeString('es-CO');
    tr.children[1].textContent = e.ep;
    tr.children[2].textContent = e.code;
    tr.children[2].classList.add(e.ok ? 'ok' : 'bad');
    tr.children[3].textContent = e.sum;
    body.appendChild(tr);
  }
}

// ---------- Eventos ----------
$('#walletLabel').textContent = BORROWER_WALLET;
$('#fileWarning').hidden = location.protocol.startsWith('http');
$('#approveBtn').addEventListener('click', approve);
$('#rejectBtn').addEventListener('click', reject);
$('#clearLog').addEventListener('click', () => { localStorage.removeItem(LOG_KEY); renderLog(); });
window.addEventListener('storage', (ev) => {
  if (ev.key !== SHARED_KEY) return;
  if (!readShared()) { ownLoan = null; offerError = ''; clearTimeout(pollTimer); pollTimer = null; }
  render();
  ensurePolling();
});

renderLog();
render();
handleReturn().then(ensurePolling);
</script>
</body>
</html>
'''
open("deudor.html", "w").write(head + extra_css + body)
print("written", len(head + extra_css + body))
PYEOF

